{
  "title": "The Mirror Rescue",
  "gate_token": "WEG9r73nLRBwgcsDjMze0g",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescuers gather at the ruined city edge.",
      "visual_description": "A shattered stone archway overlooks a city of collapsed towers and faded banners, with a glass diver adjusting his helmet and Mara studying a worn map by lamplight.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 2,
      "caption": "They pass the city gates under a rusted portcullis.",
      "visual_description": "The iron gates hang crooked, half-sunk into rubble; the team steps through cautiously as dust motes swirl in pale sunlight.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "A cursed tower looms ahead, its door sealed with glowing runes.",
      "visual_description": "A spiral tower with cracked stone and a shimmering rune-circle on its black door; the oracle lamp casts a flickering light that makes the symbols pulse.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver swims through a window reflection to unlock the door.",
      "visual_description": "He presses his helmet against a shard of mirrored glass on the ground, then his body ripples and disappears into it; inside the reflection he reaches for the door's inner latch.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "Inside the tower, they find the sleeping tax collector.",
      "visual_description": "A cluttered room with ledgers stacked like furniture; the tax collector snores on a pile of stamped papers, using a thick book as a pillow.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The oracle lamp warns of a trap in the ceiling.",
      "visual_description": "The lamp's eye glows red as it shines upward, revealing a net of razor wires suspended above the sleeping figure.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "The tin fox scouts a hallway lined with old royal banners.",
      "visual_description": "A narrow corridor hung with tattered blue-and-gold banners, some torn, some stained; the fox's metal feet click softly on the flagstones.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "Armored patrols march through the courtyard below.",
      "visual_description": "From a high window, the team watches a column of figures in dented plate armor clank across broken paving stones, their visors down and swords drawn.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The glass diver uses a puddle to cross under the patrol.",
      "visual_description": "He lies flat and slides into a rain puddle, emerging silently on the far side behind a collapsed pillar, avoiding the patrol's line of sight.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Mara reads a magical door's riddle on its stone frame.",
      "visual_description": "A door of pale crystal set in a dark arch, with glowing inscriptions that shift as she reads them aloud, compass in hand.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "The oracle lamp solves the riddle by casting a specific shadow.",
      "visual_description": "The lamp tilts its flame to throw the shadow of a gear shape onto the door; the crystal groans and swings open.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "They enter a treasury guarded by a clockwork lion.",
      "visual_description": "A vast hall lined with coin chests and jeweled goblets; a life-sized metal lion with gears exposed paces slowly before a locked iron grate.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The tin fox distracts the lion while the diver slips past.",
      "visual_description": "The small fox darts in a zigzag, winding its tail key to create a clatter; the lion turns and the diver slides through a window reflection behind it.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The sleeping tax collector wakes and stamps their permit.",
      "visual_description": "He blinks groggily, pulls a crumpled paper from his sleeve, and stamps it with a loud thump, then returns to sleep without a word.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "They descend a spiral stair toward the bridge exit.",
      "visual_description": "A crumbling staircase winding downward, with arrow slits letting in thin beams of light; dust and loose stones tumble ahead of them.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The bridge is partially collapsed and guarded by a mirror construct.",
      "visual_description": "A stone bridge arches over a chasm, its center broken into a gap; on the far side stands a humanoid shape of polished mirrors reflecting the sky.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The glass diver shatters the construct by merging with its reflection.",
      "visual_description": "He runs at the construct, dives into its mirrored surface, and emerges inside it; the construct cracks and explodes into a thousand glittering shards.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 18,
      "caption": "The team crosses the bridge to safety as the city crumbles behind them.",
      "visual_description": "They leap the gap and race across the final span, the ruined city collapsing in clouds of dust and stone; the sun breaks through ahead.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

